// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 m, uint256 v, uint256 am) internal {
        v = bound(v, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(m > 0 && v >= m && am <= v && address(this).balance >= v + 1 ether);
        try c.SetMinSum(m) {} catch { return; }
        try c.Deposit{value: v}() {} catch { return; }
        try c.Collect(am) {} catch { return; }
        assertTrue(c.balances(address(this)) == v - am && c.MinSum() == m);
    }

    function testFuzz_run(uint256 m, uint256 v, uint256 am) public {
        _run(m, v, am);
    }

    receive() external payable {}
}
